DATA.gtime = {"meta":{"title":"地质年代表（地质复习 WebApp 数据源）","standard":"ICS 国际年代地层表（2023 版及现行图表口径）","chinaRef":"舒良树《普通地质学》；南华纪/震旦纪为中国地层特色命名（分别对应国际成冰纪/埃迪卡拉纪）","updated":"2026-10-03","notes":["数值以 ICS 为准：寒武纪底界 538.8 Ma（旧值 541）；奥陶纪底界 486.85 Ma（旧值 485.4）。","白垩纪底界取 145.0 Ma（ICS 官方口径）；近年标定 Berriasian 底约 143.1±0.6 Ma，侏罗/白垩系界线是唯一无 GSSP 的系级界线，新图表可能改用 143.1。","太古宙底界取 ICS 现行图表 4031 Ma；国内教材常用 4000 Ma（部分用 3800 Ma），前寒武界线均非正式定义。","第四纪底界 2.58 Ma（2019 年前文献为 2.588），国内教材常约取 2.6 Ma。","所有 age 单位为 Ma（百万年前）；endMa=0 表示至今。"]},"eons":[{"name":"显生宙","en":"Phanerozoic","startMa":538.8,"note":"寒武纪生命大爆发以来化石记录丰富的「看得见生命」时代，仅占地球历史约12%"},{"name":"元古宙","en":"Proterozoic","startMa":2500,"note":"真核与多细胞生物出现、大气氧化、哥伦比亚-罗迪尼亚超大陆聚散"},{"name":"太古宙","en":"Archean","startMa":4031,"note":"最早生命痕迹（叠层石、有机碳）、陆核形成、条带状铁建造（BIF）；国内教材常用4000 Ma"},{"name":"冥古宙","en":"Hadean","startMa":4567,"note":"地球形成与月球大碰撞，最老锆石约44亿年，原始海洋出现；无正式地层划分"}],"eras":[{"eon":"显生宙","name":"新生代","en":"Cenozoic","startMa":66,"endMa":0,"note":"哺乳动物与被子植物时代；喜马拉雅运动塑造现今地貌"},{"eon":"显生宙","name":"中生代","en":"Mesozoic","startMa":251.9,"endMa":66,"note":"爬行动物（恐龙）时代；潘基亚超大陆裂解；中国东部燕山运动"},{"eon":"显生宙","name":"古生代","en":"Paleozoic","startMa":538.8,"endMa":251.9,"note":"海洋无脊椎动物繁盛到生物全面登陆；加里东、海西运动"},{"eon":"元古宙","name":"新元古代","en":"Neoproterozoic","startMa":1000,"endMa":538.8,"note":"雪球地球与埃迪卡拉（前寒武纪末）动物群；华南南华系-震旦系为中国标准剖面"},{"eon":"元古宙","name":"中元古代","en":"Mesoproterozoic","startMa":1600,"endMa":1000,"note":"真核生物多细胞化；华北燕山蓟县剖面（高于庄组等）为全球中元古界经典"},{"eon":"元古宙","name":"古元古代","en":"Paleoproterozoic","startMa":2500,"endMa":1600,"note":"大氧化事件（GOE）、苏必利尔型BIF成铁高峰；中国五台运动、吕梁运动"},{"eon":"太古宙","name":"新太古代","en":"Neoarchean","startMa":2800,"endMa":2500,"note":"华北陆块陆核定型关键期（阜平运动）；五台山、泰山杂岩"},{"eon":"太古宙","name":"中太古代","en":"Mesoarchean","startMa":3200,"endMa":2800,"note":"陆核持续增生，记录稀少"},{"eon":"太古宙","name":"古太古代","en":"Paleoarchean","startMa":3600,"endMa":3200,"note":"最古老生命遗迹之一（斯泰克芬叠层石，约34.5亿年）"},{"eon":"太古宙","name":"始太古代","en":"Eoarchean","startMa":4031,"endMa":3600,"note":"最老岩石：加拿大阿卡斯塔片麻岩（约40.3亿年）；中国鞍山白家坟花岗岩约38亿年"}],"periods":[{"era":"新生代","name":"第四纪","en":"Quaternary","startMa":2.58,"endMa":0,"color":"#F9F97F","note":"冰期-间冰期交替·人类出现；黄土高原风成堆积；国内教材常约取2.6 Ma","epochs":[{"name":"全新世","en":"Holocene","startMa":0.0117,"endMa":0,"note":"冰后期气候转暖，人类文明史（距今约11700年至今）"},{"name":"更新世","en":"Pleistocene","startMa":2.58,"endMa":0.0117,"note":"多次冰期旋回、猛犸象-披毛犀动物群，从直立人到智人"}]},{"era":"新生代","name":"新近纪","en":"Neogene","startMa":23.03,"endMa":2.58,"color":"#FFE619","note":"草原扩张·青藏高原隆升主期·古猿向人科演化","epochs":[{"name":"上新世","en":"Pliocene","startMa":5.333,"endMa":2.58,"note":"东非人科兴起（南方古猿→早期人属），气候趋冷"},{"name":"中新世","en":"Miocene","startMa":23.03,"endMa":5.333,"note":"草本植物大扩张，哺乳动物现代化，青藏高原快速隆升"}]},{"era":"新生代","name":"古近纪","en":"Paleogene","startMa":66,"endMa":23.03,"color":"#FD9A52","note":"哺乳动物辐射·喜马拉雅（造山）运动启动；旧称「第三纪老第三纪」已废弃","epochs":[{"name":"渐新世","en":"Oligocene","startMa":33.9,"endMa":23.03,"note":"全球变冷，南极冰盖形成，草原生态系统出现"},{"name":"始新世","en":"Eocene","startMa":56,"endMa":33.9,"note":"哺乳动物大型化与分异；始新世极热事件（PETM之后最高温）"},{"name":"古新世","en":"Paleocene","startMa":66,"endMa":56,"note":"K-Pg大灭绝后哺乳动物迅速辐射，被子植物成主导"}]},{"era":"中生代","name":"白垩纪","en":"Cretaceous","startMa":145,"endMa":66,"color":"#7FC64E","note":"被子植物兴起·辽西热河生物群（带羽毛恐龙、始祖鸟后裔类群）；末期K-Pg大灭绝；底界145.0为ICS官方值，近年标定约143.1","epochs":[]},{"era":"中生代","name":"侏罗纪","en":"Jurassic","startMa":201.4,"endMa":145,"color":"#34B2C9","note":"恐龙鼎盛·云南禄丰龙；裸子植物与菊石繁盛；中国燕山运动主幕","epochs":[]},{"era":"中生代","name":"三叠纪","en":"Triassic","startMa":251.9,"endMa":201.4,"color":"#812B92","note":"潘基亚（盘古）超大陆·恐龙与哺乳动物出现；末期大灭绝后恐龙称霸","epochs":[]},{"era":"古生代","name":"二叠纪","en":"Permian","startMa":298.9,"endMa":251.9,"color":"#F04028","note":"联合古陆形成·峨眉山玄武岩大火成岩省；末期发生史上最大灭绝","epochs":[]},{"era":"古生代","name":"石炭纪","en":"Carboniferous","startMa":358.9,"endMa":298.9,"color":"#67A599","note":"全球性成煤期·蕨类森林与巨型昆虫；华北本溪组、太原组煤层；爬行动物出现","epochs":[]},{"era":"古生代","name":"泥盆纪","en":"Devonian","startMa":419.2,"endMa":358.9,"color":"#CB8C37","note":"鱼类时代·肉鳍鱼登陆演化出两栖类；晚期发生大灭绝","epochs":[]},{"era":"古生代","name":"志留纪","en":"Silurian","startMa":443.8,"endMa":419.2,"color":"#B3E1B6","note":"维管植物（裸蕨）登陆·有颌鱼类出现；扬子区笔石相页岩","epochs":[]},{"era":"古生代","name":"奥陶纪","en":"Ordovician","startMa":486.85,"endMa":443.8,"color":"#009270","note":"头足类（鹦鹉螺）与笔石繁盛·华北广布碳酸盐岩；末期首次生物大灭绝；底界486.85为ICS新值（旧485.4）","epochs":[]},{"era":"古生代","name":"寒武纪","en":"Cambrian","startMa":538.8,"endMa":486.85,"color":"#7FA056","note":"生命大爆发·云南澄江生物群（帽天山）；三叶虫时代；底界538.8为ICS新值（旧541）","epochs":[]},{"era":"新元古代","name":"震旦纪（埃迪卡拉纪）","en":"Ediacaran","startMa":635,"endMa":538.8,"color":"#FEE4BD","note":"埃迪卡拉（软躯体）动物群·湖北三峡震旦系剖面（灯影组白云岩）为中国命名标准","epochs":[]},{"era":"新元古代","name":"南华纪（成冰纪）","en":"Cryogenian","startMa":720,"endMa":635,"color":"#CFF8FF","note":"雪球地球·华南长安组/南沱组冰碛岩，中国南华系命名自南华大冰期","epochs":[]}],"extinctions":[{"name":"奥陶纪末大灭绝","en":"End-Ordovician (O-S)","ma":443.8,"loss":"约57%属（约85%种）","cause":"冈瓦纳大陆冰川作用与海平面下降（另有火山活动-缺氧假说）","note":"五次大灭绝之首幕；笔石、三叶虫、腕足类重创"},{"name":"泥盆纪晚期大灭绝","en":"Late Devonian (F-F, Kellwasser)","ma":372.2,"loss":"约50%属（70%以上种）","cause":"海洋缺氧事件，可能与火山活动及陆源营养输入有关","note":"盾皮鱼与层孔虫-珊瑚礁生态系统崩溃；358.9 Ma Hangenberg事件二次打击"},{"name":"二叠纪末大灭绝","en":"Permian-Triassic (Great Dying)","ma":251.9,"loss":"约81%属（经典估计96%海洋种）","cause":"西伯利亚超级火山（大火成岩省）引发升温、酸化与缺氧","note":"史上最大灭绝：三叶虫、四射珊瑚、横板珊瑚彻底消失，古生代生物群终结"},{"name":"三叠纪末大灭绝","en":"Triassic-Jurassic (T-J)","ma":201.4,"loss":"约48-53%属（70-75%种）","cause":"中大西洋火成岩省（CAMP）大规模玄武岩喷发","note":"牙形石灭绝、菊石重创；空出的生态位让恐龙迅速成为陆地主宰"},{"name":"白垩纪末大灭绝","en":"Cretaceous-Paleogene (K-Pg)","ma":66,"loss":"约50%属（约75%种）","cause":"希克苏鲁伯小行星撞击（叠加德干玄武岩喷发）","note":"非鸟恐龙、菊石、箭石、沧龙与翼龙灭绝，哺乳动物与鸟类崛起"}]};
